$body = @'
<div style="background:#f5eef2;padding:40px;font-family:Arial,sans-serif;"><div style="max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);"><div style="background:#80001F;padding:28px;color:#fff;"><div style="margin-bottom:12px;"><img src="https://i.ibb.co/hRytXC3F/whitelogo.png" alt="Cakeouflage Logo" style="height:100px;display:block;"></div><p style="margin-top:10px;font-size:14px;opacity:0.9;">Luxury Cakes &bull; Crafted for Celebrations</p></div><div style="padding:40px;"><h2 style="margin-top:0;color:#1d1115;font-size:30px;">Hi {{customer_name}} &#128075;</h2><p style="color:#5f4c55;font-size:16px;line-height:1.8;">Thank you for placing your order with Cakeouflage. Your payment verification is currently pending.</p><div style="margin-top:30px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;"><h3 style="margin-top:0;color:#80001F;font-size:22px;">&#129534; Order Summary</h3><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Customer:</strong> {{customer_name}}</p><p><strong>Mobile:</strong> {{customer_phone}}</p><p><strong>Email:</strong> {{customer_email}}</p><p><strong>Item:</strong> {{item_names}}</p><p style="font-size:24px;color:#80001F;font-weight:bold;">Amount: &#8377;{{grand_total}}</p></div><div style="margin-top:25px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;">Your payment confirmation is still pending. Once verified, you will receive a confirmation email shortly.</div></div><div style="background:#140b0f;padding:30px;color:#fff;"><h3 style="margin-top:0;font-family:Georgia,serif;">Team Cakeouflage</h3><p style="color:#d7c6cc;font-size:14px;">Premium Designer Cakes crafted with elegance and creativity.</p><p style="color:#d7c6cc;font-size:14px;">&#127760; www.cakeouflage.com</p></div></div></div>
'@
$sql = "UPDATE communication_templates SET body_template='$body' WHERE id=1;"
$sql | Out-File -FilePath update_template.sql -Encoding utf8
Get-Content update_template.sql | docker exec -i cakeouflage_mysql mysql -uroot -prootpassword cakeouflage_dev
